import numpy as np
import pandas as pd

def _empty(universe):
    return pd.Series(0.0, index=pd.Index(universe), dtype=float)

def generate_weights(history, universe):
    tickers = pd.Index(universe)
    if len(tickers) == 0:
        return pd.Series(dtype=float)

    adj = history.get('adjusted_close', None)
    if adj is None:
        return _empty(tickers)

    adj = adj.reindex(columns=tickers)
    if not adj.index.is_monotonic_increasing:
        adj = adj.sort_index()

    idx = adj.index
    if len(idx) == 0:
        return _empty(tickers)

    last_date = idx[-1]
    try:
        month_start = pd.Timestamp(year=last_date.year, month=last_date.month, day=1)
        cutoff = month_start - pd.Timedelta(days=1)
        if getattr(idx, 'tz', None) is not None:
            cutoff = cutoff.tz_localize(idx.tz)
        adj_asof = adj.loc[idx <= cutoff]
    except Exception:
        adj_asof = adj

    if len(adj_asof) < 40:
        adj_asof = adj
    if len(adj_asof) < 10:
        return _empty(tickers)

    p = adj_asof.tail(300).astype(float).ffill()
    n = len(p)
    rets = p.pct_change().replace([np.inf, -np.inf], np.nan)
    last = p.iloc[-1]
    valid = last.notna() & (last > 0)

    mom_long = pd.Series(np.nan, index=tickers, dtype=float)
    mom_med = pd.Series(np.nan, index=tickers, dtype=float)
    rev = pd.Series(np.nan, index=tickers, dtype=float)
    vol = pd.Series(np.nan, index=tickers, dtype=float)

    if n >= 6:
        rev = p.iloc[-1] / p.iloc[-6] - 1.0
    if n >= 22:
        mom_med = p.iloc[-6] / p.iloc[-22] - 1.0
    elif n >= 11:
        mom_med = p.iloc[-2] / p.iloc[-11] - 1.0
    if n >= 127:
        mom_long = p.iloc[-6] / p.iloc[-127] - 1.0
    elif n >= 64:
        mom_long = p.iloc[-6] / p.iloc[-64] - 1.0
    else:
        mom_long = mom_med.copy()
    if n >= 2:
        vol = rets.tail(min(60, n - 1)).std()

    adv = pd.Series(np.nan, index=tickers, dtype=float)
    v = history.get('volume', None)
    c = history.get('close', None)
    if v is not None and c is not None:
        v = v.reindex(columns=tickers).reindex(index=adj_asof.index).tail(60)
        c = c.reindex(columns=tickers).reindex(index=adj_asof.index).tail(60)
        dv = v * c
        adv = dv.tail(20).median()

    valid = valid & mom_long.notna() & mom_med.notna() & rev.notna() & vol.notna() & (vol > 0)

    if adv.notna().sum() > 0:
        test = valid & adv.notna() & (adv > 5e5)
        if test.sum() >= 100:
            valid = test
        else:
            test = valid & adv.notna() & (adv > 1e5)
            if test.sum() >= 100:
                valid = test

    if valid.sum() < 10:
        return _empty(tickers)

    def rank(s):
        return s.where(valid).rank(pct=True, method='average')

    r1 = rank(mom_long)
    r2 = rank(mom_med)
    r3 = rank(rev)
    r4 = rank(vol)

    score = 0.45 * r1 + 0.25 * r2 - 0.25 * r3 - 0.20 * r4
    score = score.where(valid).dropna()
    if len(score) < 2:
        return _empty(tickers)

    n_side = min(50, len(score) // 2)
    if n_side < 1:
        return _empty(tickers)

    ordered = score.sort_values(ascending=False, kind='mergesort')
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    w = min(0.5 / n_side, 0.02)
    weights = pd.Series(0.0, index=tickers, dtype=float)
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    weights = weights.clip(-0.02, 0.02).replace([np.inf, -np.inf], 0.0).fillna(0.0)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights / gross

    net = weights.sum()
    if abs(net) > 0.01:
        pos = weights[weights > 0]
        neg = weights[weights < 0]
        if net > 0 and len(pos) > 0:
            weights.loc[pos.index] -= net / len(pos)
        elif net < 0 and len(neg) > 0:
            weights.loc[neg.index] -= net / len(neg)

    return weights.astype(float)

